def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find columns containing the vertical bars.
    seed_cols = set()
    for c in range(w):
        runs = []
        r = 0
        while r < h:
            if g[r][c] == 0:
                r += 1
                continue
            start = r
            while r < h and g[r][c] != 0:
                r += 1
            if r - start >= 2:
                runs.append((start, r))
        if runs:
            seed_cols.add(c)

    for c in seed_cols:
        stripes = []
        for r in range(h):
            color = g[r][c]
            if color != 0:
                continue
            # A stripe crosses this column when matching-color cells occur
            # on both sides of the gap in this row.
            left = c - 1
            while left >= 0 and g[r][left] == 0:
                left -= 1
            right = c + 1
            while right < w and g[r][right] == 0:
                right += 1
            if left >= 0 and right < w and g[r][left] == g[r][right] != 0:
                color = g[r][left]
                g[r][c] = color
                stripes.append((r, color))

        stripes.sort()
        for i, (r, color) in enumerate(stripes):
            top = 0 if i == 0 else stripes[i - 1][0] + 1
            for rr in range(top, r + 1):
                if g[rr][c] == 0:
                    g[rr][c] = color

    return g
